async function loadData(manual=false){if(loading)return;loading=true;if(manual)$('status').textContent='Verificando a versão publicada…';try{const response=await fetch('metadata.json',{cache:'no-cache'});if(!response.ok)throw Error('HTTP '+response.status);const next=await response.json();if(!Array.isArray(next.rows))throw Error('Base vazia');const prev=data?.extracted_at;if(window.areasRevision===next.areas_revision&&data)next.rows=data.rows;else window.areasReady=false;data=next;const states=[...new Set(data.rows.map(r=>r.u))].sort(),old=$('state').value;$('state').innerHTML='<option value="">Todos os estados</option>'+states.map(s=>`<option>${esc(s)}</option>`).join('');$('state').value=states.includes(old)?old:'';$('freshness').textContent='Extração dos resultados: '+new Date(data.extracted_at).toLocaleDateString('pt-BR');render();models();sources();$('status').textContent=manual?(prev===data.extracted_at?'A versão publicada continua a mesma.':'Nova versão carregada.'):'';}catch(e){$('status').textContent='Não foi possível atualizar os dados. '+(data?'A última versão continua disponível.':'Tente verificar novamente.');console.error(e)}finally{loading=false}}
function render(){if(!data)return;const rd=$('round').value,uf=$('state').value,res=$('result').value,query=fold($('search').value.trim()).replace(/(?<=\d)\.(?=\d)/g,'');filtered=data.rows.filter(r=>(!$('city')?.value||r.m.split(' / ').map(x=>x.trim()).includes($('city').value))&&(!window.onlyOthers||!['Arrematada','Conquistada','Livre'].includes(r.s))&&(!rd||r.r==rd)&&(!uf||r.u===uf)&&(!res||r.s===res)&&(!query||(fold([r.p,r.m,r.sub,r.a].join(' ')).includes(query)||(/^\d+$/.test(query)&&r.p.replace(/\D/g,'').includes(query)))));sortSelection(filtered);page=Math.min(page,Math.max(0,Math.ceil(filtered.length/size)-1));const wins=filtered.filter(r=>r.v>0),total=wins.reduce((s,r)=>s+r.v,0);$('count').textContent=num(filtered.length);$('rate').textContent=filtered.length?pct(wins.length/filtered.length):'—';$('nwin').textContent=num(wins.length)+' áreas com lance positivo';$('total').textContent=shortMoney(total);$('median').textContent=wins.length?money(median(wins.map(r=>r.v))):'—';$('scope').textContent=rd?rd+'ª rodada':'Rodadas na seleção';$('outcomes').innerHTML=Object.keys(colors).map(s=>bar(s,filtered.filter(r=>r.s===s).length,filtered.length,colors[s])).join('');const totals=[1,2,3,4,5,8].map(n=>[n,filtered.filter(r=>r.r===n).reduce((s,r)=>s+r.v,0)]),max=Math.max(...totals.map(x=>x[1]),1);$('roundbars').innerHTML=totals.map(([n,v])=>bar(n+'ª rodada',v,max,'#00775e',(v/1e6).toLocaleString('pt-BR',{maximumFractionDigits:2}))).join('');table();mapDots()}
function bar(label,value,max,color,formatted){return `<div class="bar-row"><span>${esc(label)}</span><div class="bar-track"><div class="bar-fill" style="width:${max?100*value/max:0}%;background:${color}"></div></div><span class="bar-value">${formatted??num(value)}</span></div>`}
function table(){const start=page*size,subset=filtered.slice(start,start+size);$('rows').innerHTML=subset.length?subset.map((r,i)=>`<tr><td><b>${esc(formatProcess(r.p))}</b><small>${r.r}ª rodada · área ${esc(r.a)}</small></td><td>${esc(r.m)}<small>${esc(r.u)}</small></td><td>${esc(r.sub||'Sem registro')}</td><td><span class="badge ${esc(r.s)}">${esc(r.s)}</span></td><td>${r.v?money(r.v):'Sem lance positivo'}</td><td><button class="link-button" data-index="${start+i}" aria-label="Abrir ficha do processo ${esc(formatProcess(r.p))}">Abrir ↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma área encontrada. Altere os filtros ou limpe a busca.</td></tr>';$('pagecount').textContent=filtered.length?`${num(start+1)}–${num(Math.min(start+size,filtered.length))} de ${num(filtered.length)} áreas`:'0 áreas';$('prev').disabled=page===0;$('next').disabled=start+size>=filtered.length}
function project(xy){return [(xy[0]+75)*12+25,(6-xy[1])*10+8]}
async function mapBase(){try{const r=await fetch('brasil.json');if(!r.ok)throw Error('map');const geo=await r.json();$('borders').innerHTML=geo.features.map(f=>{const polygons=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return '<path d="'+polygons.map(poly=>poly.map(ring=>ring.map((p,i)=>(i?'L':'M')+project(p).join(',')).join('')+'Z').join('')).join('')+'"/>'}).join('')}catch(e){$('mapcount').textContent='Malha indisponível'}}
