if(document.modelContext?.registerTool){const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});Promise.resolve(document.modelContext.registerTool({name:'filter_auction_areas',description:'Apply the visible round and state filters, returning observed aggregates.',inputSchema:{type:'object',properties:{round:{type:'string',enum:['','1','2','3','4','5','6','7','8']},state:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){await ensureAreas();if(!data)throw Error('Data not loaded');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['round','state'].includes(k)))throw Error('Invalid filters');if(input.round!==undefined&&!['','1','2','3','4','5','6','7','8'].includes(input.round))throw Error('Invalid round');if(input.state!==undefined&&input.state!==''&&!data.rows.some(r=>r.u===input.state))throw Error('Invalid state');if(input.round!==undefined)$('round').value=input.round;if(input.state!==undefined)$('state').value=input.state;page=0;render();return {areas:filtered.length,observedBids:filtered.reduce((s,r)=>s+r.v,0)};}},{signal:ac.signal})).catch(console.error)}
