async function changes(){try{const response=await fetch('changes.json');if(!response.ok)throw Error('changes');const d=await response.json();$('changetable').innerHTML='<table><thead><tr><th>Rodada</th><th>Áreas*</th><th>Arrematação</th><th>Lance mediano</th><th>Área mediana (ha)</th><th>Eventos prévios (média)</th></tr></thead><tbody>'+[...d.rounds].sort((a,b)=>a.round-b.round).map(r=>`<tr><td>${r.round}ª</td><td>${num(r.n)}</td><td>${pct(r.win_rate)}</td><td>${money(r.median_bid)}</td><td>${dec(r.median_area)}</td><td>${dec(r.history_mean)}</td></tr>`).join('')+'</tbody></table><p class="caption">*Resultados comerciais válidos, após exclusões. Retrato congelado do experimento de 24/09/2026.</p>';const t=d.experiment.evaluations.retrospective8,v=d.experiment.evaluations.validation5;$('changeexperiment').innerHTML=`<p>Na 8ª rodada: <b>AUC ${dec(t.auc)}</b>, Brier ${dec(t.brier)}, RMSLE ${dec(t.rmsle)} e erro absoluto médio ${money(t.mae)}.</p><p>Na validação da 5ª: Brier ${dec(v.brier)} e RMSLE ${dec(v.rmsle)}. O ganho não foi uniforme entre rodadas.</p>`;}catch(e){$('changetable').textContent='Comparação indisponível nesta versão.'}}
changes();
